const founderSection = "<section class=\"founder\"><div class=\"wrap\"><div class=\"founder-grid\"><div class=\"founder-card\"><div class=\"founder-img\"><img src=\"gaurav.jpg\" alt=\"Gaurav Bansal\"></div><div class=\"founder-bottom\"><div class=\"name\">Gaurav Bansal <span class=\"verified\">✔ Verified</span></div><div class=\"role\">Founder & CEO, AMG Venture Partners</div><a href=\"https://www.linkedin.com/in/gauravbansalventurecapital/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"linkedin-icon\">in</a> </div></div><div class=\"founder-content\"><div class=\"kicker\">• MEET THE FOUNDER</div><h2 class=\"h2\">I am Gaurav Bansal, <span>VC, operator, and founder</span></h2><ul class=\"founder-points\"><li><strong>14+ years</strong> of experience in venture capital, angel investing, investment banking, and technology consulting</li><li>Member of <strong>450+</strong> global angel investor syndicates</li><li><strong>50+</strong> tech startup investments</li><li><strong>35+</strong> venture capital portfolio companies</li><li>Investment banking deals worth <strong>$2Bn+</strong></li><li>Reviewed <strong>20k+</strong> pitch decks & financial models; conducted <strong>100+</strong> due diligence processes</li><li><strong>1000+</strong> mentor hours with founders globally</li></ul><div class=\"about-stats\"><div class=\"about-stat\"><div class=\"num\">3,000+</div><div class=\"lbl\">mentoring hours delivered</div></div><div class=\"about-stat\"><div class=\"num\">130+</div><div class=\"lbl\">founder workshops led</div></div><div class=\"about-stat\"><div class=\"num\">35+</div><div class=\"lbl\">VC portfolio companies</div></div></div><div class=\"about-eco\">— Expert-in-Residence / Evaluator at:</div><div class=\"about-eco-list\">Foresight Canada · Communitech · Volta · VentureLAB · Invest Nova Scotia · MassChallenge (US/LATAM) · Medtech Innovator ·  EIT Raw Materials · Catalist (LATAM) · D2XCEL (EU) · Spark Centre · YSpace</div><a href=\"https://www.linkedin.com/in/gauravbansalventurecapital/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"btn btn-green\">View LinkedIn Profile</a></div></div></div></section>";
const aboutSection = "<section id=\"about\" class=\"about\"><div class=\"wrap\"><h2>About AMG Venture Partners</h2><p>AMG Venture Partners is a global business consulting and technology product firm operating across the North American and European markets. We partner with incubators, accelerators, and founders (pre-seed to Series A globally) to deliver high-quality investment-readiness content and fundraising services to tech startup CEOs. We also partner directly with startup CEOs on everything fundraising.</p><p>AMG stands for Gaurav's family, where A, M, and G are the initials for the names of his father, mother, and himself.</p><p>His parents' support and motivation have played a key role in his journey from being born in a small tier 3 town in India, pursuing education, working for 10+ years in corporates and Family office VC funds, and then taking the uncertain, risky entrepreneurial route to founding AMG Venture Partners.</p><h4>What We Do</h4><ul><li>Program design, delivery, KPI tracking & reporting for incubators/accelerators</li><li>Lead Mentor / EIR for startup CEOs</li><li>Review panelist for startup applications</li><li>Prepare startups for fundraising & investor pitching</li><li>Investment readiness workshops (cohort-based)</li><li>Review technical grant applications</li><li>Stakeholder partnerships with CEOs, investors, etc.</li></ul><h4>Founder Background</h4><p>Gaurav is a tech investor and advisor with a portfolio of 35+ VC investments across 10 countries and experience in US$2Bn+ worth of IPOs, M&A, and private equity deals. He is the founder & CEO at AMG Venture Partners, where he manages his family investment portfolio (50+ startups and member of 520+ global angel syndicates) and supports founders on investment readiness & fundraising. Additionally, he serves as an Expert in Residence and Mentor across startup programs in North America, Europe, and LATAM, and specializes in investment readiness, AI/ML strategy, and global expansion.</p><h4>Clients</h4><ul><li>Worked with 15+ accelerators across US, Canada, LATAM, and EU markets, delivering 120+ programs</li><li>Supported 125+ CEOs across AI/ML, fintech, robotics, healthtech, and more</li><li>Growth driven through founder network and word-of-mouth expansion</li></ul></div></section>";
const heroSection = "<section class=\"hero-section\"> <div class=\"hero-grid\"> <!-- LEFT --> <div class=\"hero-left\"> <div class=\"hero-kicker\">Investment Readiness · By AMG Venture Partners</div> <h1 class=\"hero-title hero-title-editorial\">Become fundable <em>before</em> you fundraise.</h1> <div class=\"hero-built\"><span>Built on</span><strong>ACE</strong></div> <div class=\"hero-method\">The ACE Fundability Method™ · Assess · Create · Execute</div> <p class=\"hero-text hero-text-editorial\">Most founders raise on hope. You'll raise on a system. No fluff. No theory. No \"manifest your investor\" energy. Just the diagnostic, the materials, the strategy, and the access that turn pitches into checks.</p> </div> <!-- RIGHT --> <div class=\"hero-right\"> <!-- CARD 1 --> <div class=\"track-card track-1\"> <div class=\"track-top\"> <div class=\"track-icon\"> ◎ </div> <div> <div class=\"track-label\"> TRACK 1 </div> <h3>  Build Your Investor Foundation </h3> </div> </div> <div class=\"track-line\"></div> <p> For founders validating their idea and learning how venture fundraising actually works before raising capital. </p> </div> <!-- CARD 2 --> <div class=\"track-card track-2\"> <div class=\"track-top\"> <div class=\"track-icon\"> ◫ </div> <div> <div class=\"track-label\"> TRACK 2 </div> <h3> Investor Readiness Accelerator </h3> </div> </div> <div class=\"track-line\"></div> <p> For startups with traction preparing for an institutional raise and improving positioning, materials, and investor confidence. </p> </div> <!-- CARD 3 --> <div class=\"track-card track-3\"> <div class=\"track-top\"> <div class=\"track-icon\"> ◉ </div> <div> <div class=\"track-label\"> TRACK 3 </div> <h3> Fundraising Execution Partner </h3> </div> </div> <div class=\"track-line\"></div> <p> For investor-ready founders who need strategic outreach, investor targeting, meeting prep, and fundraising execution support. </p> </div> </div> </div> </section>";
const stats="<section class=\"trust-bar\"> <div class=\"wrap-trust\"> <div class=\"trust-stats\"> <div class=\"tstat\"> <span class=\"num\">$2 Bn+</span> <span class=\"lbl\">In IB Fundraising Deals</span> </div> <div class=\"tstat\"> <span class=\"num\">$200 Mn+</span> <span class=\"lbl\">Raised</span> </div> <div class=\"tstat\"> <span class=\"num\">20,000+</span> <span class=\"lbl\">Startups Reviewed</span> </div> <div class=\"tstat\"> <span class=\"num\">50+</span> <span class=\"lbl\">Angel Investments (pre-seed → series A)</span> </div> <div class=\"tstat\"> <span class=\"num\">350+</span> <span class=\"lbl\">Global Angel Syndicates</span> </div> <div class=\"tstat\"> <span class=\"num\">250+</span> <span class=\"lbl\">Startups Mentored</span> </div> </div> </div> </section>";
const pageHtml = "<!-- ========================= PREMIUM HEADER ========================= --> <nav class=\"nav\"> <!-- TOP HEADER --> <div class=\"nav-top\"> <!-- LOGO --> <a href=\"#\" class=\"brand\" data-action=\"home\"> <img src=\"logo.png\" alt=\"AMG Venture Partners\" class=\"brand-logo\" /> <div class=\"brand-copy\"> <div class=\"logo-main\"> AMG </div> <div class=\"logo-sub\"> VENTURE PARTNERS </div>  </div> </a> <!-- CENTER TITLE --> <div class=\"brand-program\"> <span>INVESTMENT READINESS PROGRAM</span> <div class=\"program-line\"></div> </div> </div> <!-- FLOATING MENU --> <div class=\"nav-menu\"> <div class=\"nav-links\"> <a href=\"/track-1\" data-track=\"t1\">Track 1</a> <a href=\"/track-2\" data-track=\"t2\">Track 2</a> <a href=\"/track-3\" data-track=\"t3\">Track 3</a> <a href=\"/services\" data-action=\"services\">Services</a> <a href=\"/about\" data-track=\"about\">About Us</a> <a href=\"/apply\" class=\"menu-btn\" data-action=\"applyPage\"> Apply Now </a> </div> </div> </nav>\n\n<!-- =================== LANDING =================== -->\n<div id=\"landing\" class=\"page\">\n\n"+ heroSection + stats +" <!-- PAIN -->\n  <section class=\"problem\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— The Fundraising Reality</div>\n        <h2 class=\"h2\">Most startups don’t fail at fundraising because the idea is bad.</h2>\n        <p class=\"section-sub\">Investors pass because the narrative is unclear, the positioning is weak, the traction story lacks conviction, or the founder starts outreach before the business is truly fundable. Most rejections happen long before the pitch call ends.</p>\n      </div>\n      <div class=\"pain-grid\">\n        <div class=\"pain\"><div class=\"pain-no\">01</div><div class=\"pain-q\">\"Am I even VC-fundable?\"</div><p>You don't know whether to raise, bootstrap, or chase grants — and no one will give you a straight answer.</p></div>\n        <div class=\"pain\"><div class=\"pain-no\">02</div><div class=\"pain-q\">\"My deck is beautiful but investors ghost.\"</div><p>You've spent weeks on design and storytelling. Investors still pass. The narrative isn't built for them.</p></div>\n        <div class=\"pain\"><div class=\"pain-no\">03</div><div class=\"pain-q\">\"How much should I raise? At what valuation?\"</div><p>You downloaded an Excel template, picked a number, and now you're not sure if it's defensible.</p></div>\n        <div class=\"pain\"><div class=\"pain-no\">04</div><div class=\"pain-q\">\"I emailed 200 investors. Crickets.\"</div><p>You bought a list. You sent the same teaser to everyone. The list isn't the problem — the system is.</p></div>\n        <div class=\"pain\"><div class=\"pain-no\">05</div><div class=\"pain-q\">\"They sent a SAFE — what do I sign?\"</div><p>Liquidation preferences, MFN, board seats, valuation caps. One wrong clause costs you $500K in dilution.</p></div>\n        <div class=\"pain\"><div class=\"pain-no\">06</div><div class=\"pain-q\">\"I'm ready. I just need investors.\"</div><p>Your kit is solid. Your traction is real. You don't need a course — you need access and execution.</p></div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"why-raise-fails\"> <div class=\"wrap\"> <div class=\"section-head\"> <div class=\"kicker\"> — Why Most Raises Stall </div> <h2 class=\"h2\"> Investors usually decide long before due diligence begins. </h2> <p class=\"section-sub\"> Most early-stage founders think fundraising failure happens because they need a better deck or more investor meetings. In reality, investors pass because the company does not yet look venture-backable. </p> </div> <div class=\"fails-grid\"> <div class=\"fail-card\"> <div class=\"fail-no\">01</div> <h3> Weak Positioning </h3> <p> Investors cannot quickly understand why this startup wins, why now is the right market timing, or why this becomes a large venture-scale company. </p> </div> <div class=\"fail-card\"> <div class=\"fail-no\">02</div> <h3> Unclear Narrative </h3> <p> Founders explain features and product workflows, but fail to communicate market conviction, defensibility, and long-term upside. </p> </div> <div class=\"fail-card\"> <div class=\"fail-no\">03</div> <h3> Premature Outreach </h3> <p> Many startups start emailing investors before their deck, traction story, financial model, or fundraising strategy are truly ready. </p> </div> <div class=\"fail-card\"> <div class=\"fail-no\">04</div> <h3> Lack of Investor Psychology </h3> <p> Fundraising is not just storytelling. It is understanding how investors evaluate risk, market size, timing, and return potential. </p> </div> </div> </div> </section> \n\n "+ founderSection +"   <!-- ACE METHOD -->\n  <section class=\"ace-method-section\">\n    <div class=\"wrap\">\n      <div class=\"section-head center\">\n        <div class=\"kicker\">— The ACE Fundability Method™</div>\n        <h2 class=\"h2\">Three stages. <em>One outcome.</em></h2>\n        <p class=\"section-sub\">Every founder we work with moves through these three stages. Where you are determines which program is right for you.</p>\n      </div>\n      <div class=\"ace-cards\">\n        <div class=\"ace-card a\">\n          <div class=\"ace-letter\">A</div>\n          <h4>Assess</h4>\n          <p>Diagnose your fundability honestly. Are you VC-fundable, angel-fundable, or should you bootstrap? Know your gaps before investors find them.</p>\n          <div class=\"where\"><strong>Where it lives:</strong> Foundation (1:1 Roadmap) · Investor-Ready (Pre-Cohort Diagnostic) · Outreach (Full Audit)</div>\n        </div>\n        <div class=\"ace-card c\">\n          <div class=\"ace-letter\">C</div>\n          <h4>Create</h4>\n          <p>Build the materials, exercises, and narrative investors actually evaluate. Deck, model, dataroom, Q&A — and the thinking behind each one.</p>\n          <div class=\"where\"><strong>Where it lives:</strong> Foundation (Full Content + Templates) · Investor-Ready (1:1 Sharpening + Diligence Stress Test)</div>\n        </div>\n        <div class=\"ace-card e\">\n          <div class=\"ace-letter\">E</div>\n          <h4>Execute</h4>\n          <p>Pitch. Outreach. Meet. Defend. Close. Investor list, warm intros, meeting prep, term-sheet negotiation. The kit alone doesn't raise — execution does.</p>\n          <div class=\"where\"><strong>Where it lives:</strong> Investor-Ready (Demo Day + 50-Investor List) · Outreach (Full Done-With-You)</div>\n        </div>\n      </div>\n    </div>\n  </section>\n<!-- TRACK SELECTOR -->\n  <section class=\"tracks-intro\" id=\"tracks\">\n    <div class=\"wrap\">\n      <div class=\"section-head\" >\n        <div class=\"kicker\" >— Three Tracks. One Outcome.</div>\n        <h2 class=\"h2\">Three stages. Three different fundraising problems.</h2>\n        <p class=\"section-sub\" style=\"margin-right:auto\">Whether you are figuring out if you are venture-fundable, preparing for a raise, or actively pursuing investors — each track is built for a specific fundraising stage.</p>\n      </div>\n    </div>\n    <div class=\"wrap\">\n      <div class=\"tracks-grid\">\n\n        <div class=\"track-card t1\">\n          <div class=\"track-ace-badge\">A · C</div>\n          <div class=\"track-num\">Program 01 · Foundation</div>\n          <h3 class=\"track-name\">Learn the <em>fundraising game.</em></h3>\n          <p class=\"track-tag\">For first-time fundraisers. Two formats. Pick the pace that fits your life.</p>\n          <div class=\"track-meta\">\n            <div><div class=\"tmeta-l\">Stage</div><div class=\"tmeta-v\">First-time raisers</div></div>\n            <div><div class=\"tmeta-l\">Format</div><div class=\"tmeta-v\">1-day · 2-week</div></div>\n            <div><div class=\"tmeta-l\">Cohort Size</div><div class=\"tmeta-v\">Up to 20</div></div>\n            <div><div class=\"tmeta-l\">ACE Stage</div><div class=\"tmeta-v\">Assess + Create</div></div>\n          </div>\n          <ul class=\"track-bullets\">\n            <li>All 6 content modules taught live</li>\n            <li>1-day intensive · or · 2-week sprint</li>\n            <li>All templates, exercises, tools — lifetime</li>\n            <li>1 × 1:1 strategic roadmap session</li>\n            <li>Post-program group AMA</li>\n          </ul>\n          <div class=\"track-price\">$997 <small>early bird · then $1,497 + HST</small></div>\n          <a href=\"#\" class=\"track-cta\" data-track=\"t1\">Become fundable <span>→</span></a>\n        </div>\n\n        <div class=\"track-card t2\">\n          <div class=\"track-ace-badge\">A · C · E</div>\n          <div class=\"track-num\">Program 02 · Investor-Ready</div>\n          <h3 class=\"track-name\">From <em>pitch</em> to Demo Day.</h3>\n          <p class=\"track-tag\">For founders with traction raising in 3–6 months. Diagnostic. 1:1 sharpening. Real demo day.</p>\n          <div class=\"track-meta\">\n            <div><div class=\"tmeta-l\">Stage</div><div class=\"tmeta-v\">Post-MVP + traction</div></div>\n            <div><div class=\"tmeta-l\">Format</div><div class=\"tmeta-v\">8-Wk Pitch→Demo Day</div></div>\n            <div><div class=\"tmeta-l\">Cohort Size</div><div class=\"tmeta-v\">Up to 20</div></div>\n            <div><div class=\"tmeta-l\">ACE Stage</div><div class=\"tmeta-v\">Full A + C + E</div></div>\n          </div>\n          <ul class=\"track-bullets\">\n            <li>Pre-cohort Investor Readiness Review (1:1)</li>\n            <li>3 × 1:1 deep-dive feedback sessions</li>\n            <li>The Diligence Stress Test</li>\n            <li>Demo Day with real investor panel</li>\n            <li>Customized 50-investor target list</li>\n            <li>Investor Roundtable — lifetime alumni access</li>\n          </ul>\n          <div class=\"track-price\">$3,997 <small>+ HST · application-based</small></div>\n          <a href=\"#\" class=\"track-cta\" data-track=\"t2\">Get pressure-tested <span>→</span></a>\n        </div>\n\n        <div class=\"track-card t3\">\n          <div class=\"track-ace-badge\">E</div>\n          <div class=\"track-num\">Program 03 · Outreach</div>\n          <h3 class=\"track-name\">Get in <em>front</em> of investors.</h3>\n          <p class=\"track-tag\">For investor-ready founders raising now. Done-with-you outreach. Broker-dealer compliant.</p>\n          <div class=\"track-meta\">\n            <div><div class=\"tmeta-l\">Stage</div><div class=\"tmeta-v\">Investor-ready</div></div>\n            <div><div class=\"tmeta-l\">Format</div><div class=\"tmeta-v\">~6-Mo 1:1 Engagement</div></div>\n            <div><div class=\"tmeta-l\">Spots</div><div class=\"tmeta-v\">Selective · Rolling</div></div>\n            <div><div class=\"tmeta-l\">ACE Stage</div><div class=\"tmeta-v\">Pure Execute</div></div>\n          </div>\n          <ul class=\"track-bullets\">\n            <li>Full readiness audit + investor list build</li>\n            <li>50–100 vetted target investors, activated</li>\n            <li>Weekly 1:1 strategy + meeting prep</li>\n            <li>Term-sheet review + negotiation coaching</li>\n            <li>Registered broker-dealer partnership</li>\n          </ul>\n          <div class=\"track-price\">From $4K <small>+ taxes · two fee structures · negotiable</small></div>\n          <a href=\"#\" class=\"track-cta\" data-track=\"t3\">Get me in front of investors <span>→</span></a>\n        </div>\n      </div>\n    </div>\n  </section>  <!-- HOW TO START -->\n  <section class=\"howto-section\" id=\"how-to-start\">\n    <div class=\"wrap\">\n      <div class=\"section-head center\">\n        <div class=\"kicker\">— How to Start</div>\n        <h2 class=\"h2\">Tell us where you are. <em>We'll tell you what fits.</em></h2>\n        <p class=\"section-sub\">Most founders don't know what they don't know — and most feel they don't need the knowledge. We've seen it 150+ times. So we don't ask you to self-route. You apply. We talk. We agree on the right path together.</p>\n      </div>\n      <div class=\"howto-steps\">\n        <div class=\"howto-step\">\n          <div class=\"howto-num\">01</div>\n          <div class=\"howto-content\">\n            <h4>You apply</h4>\n            <p>Fill the application form. 11 questions. 5–7 minutes. Tell us where you are, what you've built, when you're raising, and which program you think fits.</p>\n          </div>\n        </div>\n        <div class=\"howto-step\">\n          <div class=\"howto-num\">02</div>\n          <div class=\"howto-content\">\n            <h4>We talk</h4>\n            <p>20–30 minute fit call with Gaurav within 48 hours. We dig into your situation honestly. We say no to ~40% of applicants because the fit isn't right — and we'd rather tell you upfront than waste your runway.</p>\n          </div>\n        </div>\n        <div class=\"howto-step\">\n          <div class=\"howto-num\">03</div>\n          <div class=\"howto-content\">\n            <h4>We agree the right path</h4>\n            <p>Maybe Foundation. Maybe Investor-Ready. Maybe Outreach. Maybe an à-la-carte service. Maybe you're not fundable yet and we tell you so. Whatever it is — the decision is collaborative, not pushed.</p>\n          </div>\n        </div>\n      </div>\n      <div class=\"howto-cta\">\n        <a href=\"/apply\" class=\"btn btn-primary\" data-action=\"applyPage\">Start your application <span class=\"arr\">→</span></a>\n      </div>\n    </div>\n  </section>\n\n\n  <!-- AD-HOC SERVICES (links out) -->\n  <section class=\"adhoc\" id=\"services\">\n    <div class=\"wrap\">\n      <div class=\"adhoc-inner\">\n        <div>\n          <div class=\"kicker\">— Need just one piece? Don't need a full program?</div>\n          <h3>Tackle a single deliverable with <em>à-la-carte services.</em></h3>\n          <p>Whether you're inside a program and want done-for-you work on a specific deliverable, or you only need one targeted piece — pick exactly what you need from the standalone services menu.</p>\n          <a href=https://amgvp.com/ class=\"btn btn-yellow\">Browse all services <span class=\"arr\">→</span></a>\n        </div>\n        <div class=\"adhoc-list\">\n          <span>Investor Readiness Review</span>\n          <span>Pitch Deck Review</span>\n          <span>Pitch Deck Creation</span>\n          <span>Financial Model Build</span>\n          <span>Valuation Analysis</span>\n          <span>Fundraising Dynamics</span>\n          <span>Investor Q&A Prep</span>\n          <span>Cap Table Simulation</span>\n          <span>Term-Sheet Review</span>\n          <span>Ask-Me-Anything 1:1</span>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- FINALE -->\n      <section class=\"finale\" id=\"finale\"> <div class=\"wrap\"> <div class=\"kicker\"> — Fundraising Starts Before Investor Outreach </div> <h2> Find out what investors will question before you start fundraising. </h2> <p> Whether you are still validating your business, preparing your investor materials, or actively planning a raise — we will help you identify the gaps, pressure-test your strategy, and determine the right fundraising path. </p> <div class=\"finale-points\"> <div class=\"fpoint\"> Investor readiness assessment </div> <div class=\"fpoint\"> Fundraising strategy review </div> <div class=\"fpoint\"> Investor narrative feedback </div> <div class=\"fpoint\"> Track recommendation based on stage </div> </div> <a href=\"#\" class=\"btn btn-yellow\" data-action=\"callPage\"> Book Your Fundraising Strategy Call <span class=\"arr\">→</span> </a> </div> </section>\n\n</div>     <div id=\"t4-page\" class=\"track-page t4-page\">\n\n  <section class=\"thero t4-hero\">\n  </section></div>\n\n\n<!-- ================= TRACK 1 · FOUNDATION ================= -->\n<div id=\"t1-page\" class=\"track-page t1-page\">\n\n  <section class=\"thero t1-hero\">\n    <div class=\"wrap\">\n      <button class=\"thero-back\" data-action=\"home\">← All Programs</button>\n      <div class=\"thero-grid\">\n        <div>\n          <div class=\"thero-eyebrow\">Program 01 · Foundation</div>\n          <h1 class=\"thero-title\">Become <em>fundable</em> before you spend a year proving you're not.</h1>\n          <div class=\"thero-ace\">\n            <span class=\"ace-chip\">A · C</span> The Assess + Create stages of the ACE Fundability Method™\n          </div>\n          <p class=\"thero-sub\">For first-time fundraisers. Learn what investors actually evaluate — what they ignore — and what kills the deal. Walk out with a diagnosed fundability scorecard, every template an investor will ask for, and a personal roadmap for the next 12 months. Two formats: 1-day intensive or 2-week sprint.</p>\n          <div class=\"hero-ctas\">\n            <a href=\"#\" class=\"btn btn-primary\" data-action=\"applyPage\">Apply to next cohort <span class=\"arr\">→</span></a>\n            <a href=\"#t1-formats\" class=\"btn btn-ghost\">See the 2 formats</a>\n          </div>\n          <div class=\"thero-meta\">\n            <div class=\"thero-mcell\"><div class=\"lbl\">Formats</div><div class=\"val\">1-day · 2-week</div></div>\n            <div class=\"thero-mcell\"><div class=\"lbl\">Delivery</div><div class=\"val\">Live · Virtual</div></div>\n            <div class=\"thero-mcell\"><div class=\"lbl\">Cohort Size</div><div class=\"val\">Up to 20</div></div>\n            <div class=\"thero-mcell\"><div class=\"lbl\">Investment</div><div class=\"val\">$997 → $1,497</div></div>\n          </div>\n        </div>\n        <div class=\"thero-visual\">\n          <div class=\"visual-card\">\n            <div class=\"vc-badge\">Foundation</div>\n            <div class=\"vc-title\" style=\"margin-top:28px\">What you'll have:</div>\n            <div class=\"vc-line\"><span class=\"l\">Your fundability scorecard</span><span class=\"v\">✓</span></div>\n            <div class=\"vc-line\"><span class=\"l\">All 6 modules of frameworks</span><span class=\"v\">✓</span></div>\n            <div class=\"vc-line\"><span class=\"l\">Every template + exercise</span><span class=\"v\">✓</span></div>\n            <div class=\"vc-line\"><span class=\"l\">1:1 roadmap with Gaurav</span><span class=\"v\">✓</span></div>\n            <div class=\"vc-line\"><span class=\"l\">Group AMA after program</span><span class=\"v\">✓</span></div>\n            <div class=\"vc-line\"><span class=\"l\">Lifetime template access</span><span class=\"v\">✓</span></div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"duo\">\n    <div class=\"wrap\">\n      <div class=\"duo-grid\">\n        <div class=\"duo-card bad\">\n          <h3>Be honest. Is this you?</h3>\n          <p class=\"sub\">— Most first-time founders won't admit any of this out loud.</p>\n          <ul class=\"duo-list\">\n            <li>You've been told to \"just talk to investors.\" You don't know what to say.</li>\n            <li>You've watched 40 YouTube videos on pitch decks and you're more confused than before.</li>\n            <li>You don't know what an investor actually evaluates — or whether you're even fundable.</li>\n            <li>You picked a \"raise amount\" because it sounded right. You can't defend it.</li>\n            <li>You're scared to email a real VC because you don't know what they'll ask.</li>\n            <li>You'd rather find out you're not fundable now than after burning 6 months.</li>\n          </ul>\n        </div>\n        <div class=\"duo-card good\">\n          <h3>Here's what changes.</h3>\n          <p class=\"sub\">— Inside whichever format you pick.</p>\n          <ul class=\"duo-list\">\n            <li>You'll know if you're VC-fundable, angel-fundable, or should bootstrap.</li>\n            <li>You'll have every template an investor would ask for — drafted, not pretend-built.</li>\n            <li>You'll have a defensible funding ask, valuation logic, and cap table.</li>\n            <li>You'll have a personal roadmap with Gaurav — not a generic checklist.</li>\n            <li>You'll know which red flags to fix before you reach out to anyone.</li>\n            <li>You'll have lifetime access to every template, every update, every alumni AMA.</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- 2 FORMATS -->\n  <section class=\"formats\" id=\"t1-formats\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— Pick Your Format</div>\n        <h2 class=\"h2\">Same content. Same templates. <em>Two paces.</em></h2>\n        <p class=\"section-sub\">You choose your format at registration. Both formats cover all 6 modules, deliver every template and exercise, include the closing 1:1 roadmap session, and end with a post-program group AMA. Pick what fits your calendar.</p>\n      </div>\n      <div class=\"format-grid\" style=\"grid-template-columns:repeat(2,1fr);max-width:880px;margin-left:auto;margin-right:auto\">\n\n        <div class=\"format-card\">\n          <span class=\"fc-tag\">Option 01 · The Sprint</span>\n          <h4>1-Day Intensive</h4>\n          <p class=\"fc-sub\">— All 6 modules in one day. Saturday format.</p>\n          <ul class=\"fc-bullets\">\n            <li>8 hours · live virtual · single session</li>\n            <li>All 6 modules taught back-to-back</li>\n            <li>Templates released throughout</li>\n            <li>1:1 roadmap booked the following week</li>\n            <li>Group AMA 30 days post-program</li>\n            <li>For founders who want to absorb fast</li>\n          </ul>\n        </div>\n\n        <div class=\"format-card\">\n          <span class=\"fc-tag\">Option 02 · The Sprint+</span>\n          <h4>2-Week Sprint</h4>\n          <p class=\"fc-sub\">— 6 modules over 2 weeks. Digestible pace.</p>\n          <ul class=\"fc-bullets\">\n            <li>6 sessions × 2 hours · 3 days/week</li>\n            <li>One module per session, no overlap</li>\n            <li>Templates released each session</li>\n            <li>1:1 roadmap in final week</li>\n            <li>Group AMA 30 days post-program</li>\n            <li>For founders balancing the day job</li>\n          </ul>\n        </div>\n\n      </div>\n    </div>\n  </section>\n\n  <!-- 6 MODULES -->\n  <section class=\"curriculum\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— What You'll Cover</div>\n        <h2 class=\"h2\">All 6 modules. Whichever pace <em>you pick.</em></h2>\n        <p class=\"section-sub\">Same content. Same templates. Same exercises. Different cadence. Every module ends with a tangible deliverable you'll execute yourself.</p>\n      </div>\n      <div class=\"weekly\">\n\n        <div class=\"week\">\n          <div class=\"week-num\">M1<span>Module</span></div>\n          <div>\n            <div class=\"week-tag tag-assess\"><span class=\"ace-mark\">A</span> Assess</div>\n            <div class=\"week-title\">Nuts & Bolts of Fundraising.</div>\n            <div class=\"week-desc\">How VCs actually operate. Red flags they eliminate deals on. Investor types and how to categorize them. Are you VC-fundable or angel-fundable? What's the difference? <strong>You'll leave knowing which path makes sense — and which doesn't.</strong></div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You execute</span><ul><li>Fundability scorecard for your business</li><li>Investor profile map</li><li>Raise-or-not decision</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">M2<span>Module</span></div>\n          <div>\n            <div class=\"week-tag tag-create\"><span class=\"ace-mark\">C</span> Create</div>\n            <div class=\"week-title\">Market Dynamics & Valuations.</div>\n            <div class=\"week-desc\">Real market data on rounds, valuations, dilution. Funding ask, runway, pre/post-money, target KPIs decluttered. How VCs actually value your company. <strong>No Excel template guesswork.</strong></div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You execute</span><ul><li>Funding ask + runway sheet</li><li>Defensible valuation range</li><li>Target KPI map</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">M3<span>Module</span></div>\n          <div>\n            <div class=\"week-tag tag-create\"><span class=\"ace-mark\">C</span> Create</div>\n            <div class=\"week-title\">Financial Modeling for Founders.</div>\n            <div class=\"week-desc\">Why investors care, what they ignore, how to build assumptions you can defend. Revenue lines, unit economics, hiring plan, three statements, 50–100x return narrative. <strong>You'll know what a good model looks like — and yours will look like that.</strong></div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You execute</span><ul><li>Financial model framework</li><li>Investor return scenario</li><li>KPI tracker</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">M4<span>Module</span></div>\n          <div>\n            <div class=\"week-tag tag-create\"><span class=\"ace-mark\">C</span> Create</div>\n            <div class=\"week-title\">Pitch — Flow, Content, Narrative.</div>\n            <div class=\"week-desc\">What investors look for slide-by-slide. When and which format to share. Storytelling that works — and the kind that gets you ignored. <strong>Side-by-side: good decks vs bad decks. Yours becomes one of the good ones.</strong></div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You execute</span><ul><li>Pitch deck framework</li><li>30-sec · 2-min · 5-min scripts</li><li>Forwardable teaser draft</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">M5<span>Module</span></div>\n          <div>\n            <div class=\"week-tag tag-create\"><span class=\"ace-mark\">C</span> Create</div>\n            <div class=\"week-title\">Investor Outreach Strategy.</div>\n            <div class=\"week-desc\">Target investor profile. Building an investor CRM. Ambassador army for warm intros. Email teaser playbook. Investor meetings, Q&A, decoding feedback, follow-up cadence. <strong>The system that turns lists into meetings.</strong></div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You execute</span><ul><li>Investor CRM (drafted)</li><li>Cold + warm outreach templates</li><li>Q&A bank</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">M6<span>Module</span></div>\n          <div>\n            <div class=\"week-tag tag-create\"><span class=\"ace-mark\">C</span> Create</div>\n            <div class=\"week-title\">Investment Instruments & Term Sheets.</div>\n            <div class=\"week-desc\">SAFE vs convertible vs priced round. The dangerous clauses no one tells you about — MFN, liquidation preference, board seats, drag-along. Cap table simulation pre-seed → Series B. <strong>One wrong clause costs you $500K. We map every one.</strong></div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You execute</span><ul><li>Term-sheet negotiation cheat sheet</li><li>Cap table simulation (6-yr)</li><li>Red-flag clauses checklist</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">+1<span>1:1 Session</span></div>\n          <div>\n            <div class=\"week-tag tag-assess\"><span class=\"ace-mark\">A</span> Assess · Closing</div>\n            <div class=\"week-title\">Your Strategic Roadmap (1:1).</div>\n            <div class=\"week-desc\">A 60-minute private session with Gaurav. We go through your fundability, your gaps, your timeline. <strong>You leave with a personalized fundraising roadmap — not a generic checklist.</strong> When to start. What to fix first. How to pace it.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You leave with</span><ul><li>Personalized roadmap doc</li><li>Gap priority list</li><li>Next-step decision</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">+30<span>Days Later</span></div>\n          <div>\n            <div class=\"week-tag tag-execute\"><span class=\"ace-mark\">E</span> Group AMA</div>\n            <div class=\"week-title\">Post-Program Group AMA.</div>\n            <div class=\"week-desc\">30 days after the program ends, the cohort reconvenes for a group AMA. <strong>Bring every question that came up while you were executing.</strong> Gaurav answers live, recorded for replay. Often the most valuable session of the entire program.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You receive</span><ul><li>Live Q&A with Gaurav</li><li>Cohort peer-learning</li><li>Recorded for lifetime access</li></ul></div>\n        </div>\n\n      </div>\n    </div>\n  </section>\n\n  <!-- TEMPLATES VAULT -->\n  <section class=\"vault\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— Every Template. Every Exercise.</div>\n        <h2 class=\"h2\">Templates investors expect. <em>Frameworks they don't see coming.</em></h2>\n        <p class=\"section-sub\">All templates and exercises delivered across the 6 modules. Yours for life. Updated quarterly. No upcharge.</p>\n      </div>\n      <div class=\"vault-grid\">\n        <div class=\"vault-item\"><div class=\"ico\">01</div><h4>Pitch Deck Templates</h4><p>Multiple formats + good/bad examples library.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">02</div><h4>Funding Ask Builder</h4><p>Ask, valuation, dilution, runway — one combined template.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">03</div><h4>Cap Table Simulator</h4><p>Pre-seed through Series B dilution scenarios.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">04</div><h4>Email Teaser Pack</h4><p>Cold + forwardable templates that get opened.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">05</div><h4>Investor CRM</h4><p>Pre-built tabs for outreach + follow-up tracking.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">06</div><h4>Outreach Sequences</h4><p>Cold + warm email cadences that actually convert.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">07</div><h4>Warm-Intro Template</h4><p>Ambassador outreach request that gets forwarded.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">08</div><h4>Dataroom Structure</h4><p>Folder structure + checklist diligence demands.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">09</div><h4>Investor Q&A Bank</h4><p>50+ real questions with sharp answers.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">10</div><h4>Term-Sheet Toolkit</h4><p>Review checklist + red-flag clauses cheat sheet.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">11</div><h4>Investor Target List</h4><p>Filterable database + scoring rubric.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">12</div><h4>IR Roadmap / Tracker</h4><p>Investment Readiness roadmap + tracker template. Plan it. Track it. Hold yourself accountable.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">E1</div><h4>15 Exercises</h4><p>Fundability scorecard · valuation · storytelling · objection-handling · diligence Q&A simulation · more.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">T1</div><h4>Sector Benchmarks</h4><p>Real valuation data + KPI benchmarks by sector.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">T2</div><h4>Investor Database</h4><p>Curated angels + VCs + family offices.</p></div>\n      </div>\n    </div>\n  </section>\n\n  <!-- ANTI-SELL -->\n  <section class=\"antisell\">\n    <div class=\"wrap\">\n      <div class=\"section-head center\">\n        <div class=\"kicker\">— Real Talk Before You Buy</div>\n        <h2 class=\"h2\">This isn't for everyone. <em>Read this first.</em></h2>\n      </div>\n      <div class=\"antisell-grid\">\n        <div class=\"antisell-card dont\">\n          <h4>Don't buy Foundation if:</h4>\n          <ul>\n            <li>You expect Gaurav to build your deck or model. He won't. That's à-la-carte.</li>\n            <li>You're not willing to do the exercises. The templates are useless if you skip the work.</li>\n            <li>You want investor introductions. Not what this is. Look at Outreach.</li>\n            <li>You already have an MVP and traction. You're past Foundation — go Investor-Ready.</li>\n            <li>You want a guarantee of raising capital. Nobody legitimate offers that.</li>\n          </ul>\n        </div>\n        <div class=\"antisell-card do\">\n          <h4>Buy Foundation if:</h4>\n          <ul>\n            <li>You're a first-time fundraiser and want to understand the game.</li>\n            <li>You're willing to execute exercises between sessions, not just consume content.</li>\n            <li>You'd rather hear \"you're not fundable yet\" from Gaurav than from a real VC.</li>\n            <li>You want lifetime access to every template, exercise, and AMA.</li>\n            <li>You want to know exactly what to fix before you reach out to investors.</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- WHY NOW -->\n  <section class=\"whynow\">\n    <div class=\"wrap\">\n      <div class=\"whynow-card\">\n        <div class=\"whynow-num\">6</div>\n        <div>\n          <div class=\"kicker\">— Why Now</div>\n          <h3>Every month you delay learning is a month closer to <em>running out of runway with no plan.</em></h3>\n          <p>The best time to learn the fundraising game was 6 months ago. The second-best time is the next cohort. Founders who wait until they \"need to raise\" almost always raise wrong — under pressure, with the wrong investors, at the wrong terms. Foundation exists so you can raise from a position of clarity, not panic.</p>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- PRICING -->\n  <section class=\"pricing\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— Investment</div>\n        <h2 class=\"h2\">$997 if you're early. <em>$1,497 otherwise.</em></h2>\n      </div>\n      <div class=\"price-card\">\n        <div>\n          <div class=\"price-amt\">\n            $997\n            <small>USD + HST · early bird (first 5 seats) · then $1,497</small>\n            <em>Cofounder seat: +$297</em>\n          </div>\n          <div class=\"price-anchor\">\n            <strong>Compared to:</strong>\n            <ul>\n              <li>~1 hour with a fundraising consultant ($800–1,500/hr)</li>\n              <li>The opportunity cost of a 6-month failed raise (~$50K+)</li>\n              <li>One bad term-sheet clause you'd sign without knowing ($500K+ dilution)</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"price-includes\">\n          <h4>— What's included</h4>\n          <ul>\n            <li>All 6 modules taught live in your chosen format</li>\n            <li>1 × 1:1 strategic roadmap session with Gaurav</li>\n            <li>Post-program group AMA (30 days after end)</li>\n            <li>All 12 templates · all 15 exercises · all 3 tools</li>\n            <li>1-year recordings + lifetime template access</li>\n            <li>Private founder community (lifetime)</li>\n            <li>12 months of program updates</li>\n            <li>Bidirectional cross-link to à-la-carte services</li>\n          </ul>\n          <div class=\"price-seats\"><span class=\"dot\"></span><strong>First 5 seats at $997.</strong>&nbsp;Seats 6–20: $1,497.</div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- AD-HOC LINK -->\n  <section class=\"adhoc\">\n    <div class=\"wrap\">\n      <div class=\"adhoc-inner\">\n        <div>\n          <div class=\"kicker\">— Want one piece done-for-you?</div>\n          <h3>Top up Foundation with <em>à-la-carte services.</em></h3>\n          <p>Foundation gives you frameworks and feedback. If you want me to actually build a piece for you — a polished pitch deck, a full financial model, a valuation analysis — those live in the à-la-carte services menu. Stack what you need.</p>\n          <a href=\"https://amgvp.com/\" class=\"btn btn-yellow\">Browse all services <span class=\"arr\">→</span></a>\n        </div>\n        <div class=\"adhoc-list\">\n          <span>Pitch Deck Creation</span>\n          <span>Financial Model Build</span>\n          <span>Valuation Analysis</span>\n          <span>Investor Readiness Review</span>\n          <span>Pitch Deck Review</span>\n          <span>Ask-Me-Anything 1:1</span>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- FAQ -->\n  <section class=\"faq\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— Founder Objections</div>\n        <h2 class=\"h2\">Real questions. <em>Real answers.</em></h2>\n      </div>\n      <div class=\"faq-list\">\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">\"Which format should I pick?\"<span class=\"plus\">+</span></div><div class=\"faq-a\">Pick based on your calendar, not your impatience. The 1-day intensive works if you can absorb 8 hours in a row and execute alone after. The 2-week sprint (6 sessions × 2 hours, 3 days/week) is the more digestible option. Same content, same templates, same outcome. Different cadence. Indicate your preference on the application.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">\"Can't I just learn this from YouTube?\"<span class=\"plus\">+</span></div><div class=\"faq-a\">Sure. So can your competitors. The difference: YouTube doesn't tell you you're wrong. We do. Repeatedly. Until you're right. Plus you get the templates, the exercises, the 1:1 roadmap, and the AMA — none of which YouTube provides.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">\"What if I realize halfway through I'm not VC-fundable?\"<span class=\"plus\">+</span></div><div class=\"faq-a\">That's a successful outcome. Better to find out in week 2 than 6 months into a failed raise. We'll redirect you to angels, grants, revenue-based financing, or bootstrapping — whichever makes sense for you. Knowing what NOT to do is half the win.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">\"Can my cofounder join too?\"<span class=\"plus\">+</span></div><div class=\"faq-a\">Yes. Cofounder seat is +$297. Full community + workshop access for both of you. Fundraising is a team sport — having both aligned is worth the small premium.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">\"I've already done an accelerator. Why this?\"<span class=\"plus\">+</span></div><div class=\"faq-a\">Accelerators teach you to be a founder. We teach you to raise capital. Different skills. Most accelerators give you a stage; we give you a system. Most have a demo day; we have a method.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">\"Is there a refund if I hate it?\"<span class=\"plus\">+</span></div><div class=\"faq-a\">Yes. The 14-Day Truth Promise: if after the first 2 weeks you don't think you're getting at least 10x the price in value, email Gaurav. Full refund. Keep the templates as a thank-you for trying. Most founders never claim it.</div></div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"finale\">\n    <div class=\"wrap\">\n      <h2>Find out if you're <em>VC-fundable.</em></h2>\n      <p>Application is short — 5 questions, 10 minutes. We respond within 48 hours.</p>\n      <a href=\"#\" class=\"btn btn-yellow\" data-action=\"applyPage\">Start your application <span class=\"arr\">→</span></a>\n    </div>\n  </section>\n\n</div>\n\n<!-- ================= TRACK 2 · INVESTOR-READY ================= -->\n<div id=\"t2-page\" class=\"track-page t2-page\">\n\n  <section class=\"thero t2-hero\">\n    <div class=\"wrap\">\n      <button class=\"thero-back\" data-action=\"home\">← All Programs</button>\n      <div class=\"thero-grid\">\n        <div>\n          <div class=\"thero-eyebrow\">Program 02 · Investor-Ready</div>\n          <h1 class=\"thero-title\">Your raise is going to fail. <em>Unless</em> you fix what's broken first.</h1>\n          <div class=\"thero-ace\">\n            <span class=\"ace-chip\">A · C · E</span> The full ACE Fundability Method™ — Assess. Create. Execute.\n          </div>\n          <p class=\"thero-sub\">For founders with traction raising in 3–6 months. From your current pitch to a real Demo Day in 8 weeks. Diagnostic. Sharpening. Pressure-testing. Live panel pitch. 1:1 access to Gaurav throughout. Application-based.</p>\n          <div class=\"hero-ctas\">\n            <a href=\"#\" class=\"btn btn-primary\" data-action=\"applyPage\">Apply to next cohort <span class=\"arr\">→</span></a>\n            <a href=\"#t2-curriculum\" class=\"btn btn-ghost\">See the 5-phase journey</a>\n          </div>\n          <div class=\"thero-meta\">\n            <div class=\"thero-mcell\"><div class=\"lbl\">Format</div><div class=\"val\">8 Wk · Pitch → Demo Day</div></div>\n            <div class=\"thero-mcell\"><div class=\"lbl\">Delivery</div><div class=\"val\">Group + 1:1</div></div>\n            <div class=\"thero-mcell\"><div class=\"lbl\">Cohort Size</div><div class=\"val\">Up to 20</div></div>\n            <div class=\"thero-mcell\"><div class=\"lbl\">Investment</div><div class=\"val\">$3,997 + HST</div></div>\n          </div>\n        </div>\n        <div class=\"thero-visual\">\n          <div class=\"visual-card\">\n            <div class=\"vc-badge\">Investor-Ready</div>\n            <div class=\"vc-title\" style=\"margin-top:28px\">By Week 8 you'll have:</div>\n            <div class=\"vc-line\"><span class=\"l\">Diagnostic + roadmap</span><span class=\"v\">✓</span></div>\n            <div class=\"vc-line\"><span class=\"l\">Sharpened deck + model + script</span><span class=\"v\">✓</span></div>\n            <div class=\"vc-line\"><span class=\"l\">Survived the Diligence Stress Test</span><span class=\"v\">✓</span></div>\n            <div class=\"vc-line\"><span class=\"l\">Pitched a real investor panel</span><span class=\"v\">✓</span></div>\n            <div class=\"vc-line\"><span class=\"l\">50 vetted investors to target</span><span class=\"v\">✓</span></div>\n            <div class=\"vc-line\"><span class=\"l\">Lifetime Investor Roundtable</span><span class=\"v\">✓</span></div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"duo\">\n    <div class=\"wrap\">\n      <div class=\"duo-grid\">\n        <div class=\"duo-card bad\">\n          <h3>Be honest. Is this you?</h3>\n          <p class=\"sub\">— Closer than you think. Just not converting.</p>\n          <ul class=\"duo-list\">\n            <li>You have an MVP, users or revenue, but investors aren't biting on your deck.</li>\n            <li>You've pitched at 3 demo days, sent 80 emails, gotten 4 meetings — and 4 polite passes.</li>\n            <li>Your financial model has nice numbers but you can't defend a single assumption under pressure.</li>\n            <li>You don't know if your ask is too high, too low, or just wrong for your stage.</li>\n            <li>You need speed. You don't have 12 weeks to take a course. You're raising in months, not years.</li>\n            <li>You'd rather get torn apart by Gaurav in a private 1:1 than by a real VC in front of his partners.</li>\n          </ul>\n        </div>\n        <div class=\"duo-card good\">\n          <h3>Here's what changes.</h3>\n          <p class=\"sub\">— Eight weeks from now.</p>\n          <ul class=\"duo-list\">\n            <li>Your deck has been torn apart, rebuilt, and stress-tested through a real investor lens.</li>\n            <li>Your financial model defends every assumption. Your ask is rational. Your dilution is mapped.</li>\n            <li>You'll have survived the Diligence Stress Test — every question a real VC will ask, asked first.</li>\n            <li>You'll have pitched a panel of real angels and VCs at Demo Day. With recordings to prove it.</li>\n            <li>You'll have a customized 50-investor target list — built by Gaurav, not scraped from a database.</li>\n            <li>You'll have lifetime access to the Investor Roundtable — monthly group VC Q&As, forever.</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- 5-PHASE CURRICULUM -->\n  <section class=\"curriculum\" id=\"t2-curriculum\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— The 5-Phase Journey · 8 Weeks</div>\n        <h2 class=\"h2\">Pitch on day 1. <em>Demo Day on week 8.</em></h2>\n        <p class=\"section-sub\">Five phases mapped to the ACE Fundability Method™. Content in 2 weeks. Sharpening over 4 weeks. Diligence Stress Test in weeks 5–6. Demo Day in week 8.</p>\n      </div>\n      <div class=\"weekly\">\n\n        <div class=\"week\">\n          <div class=\"week-num\">0<span>Pre-Cohort</span></div>\n          <div>\n            <div class=\"week-tag tag-assess\"><span class=\"ace-mark\">A</span> Assess · Phase 1</div>\n            <div class=\"week-title\">Investor Readiness Review.</div>\n            <div class=\"week-desc\">Before the cohort even starts: a private 90-minute 1:1 with Gaurav. You submit your current materials — deck, model, dataroom, hygiene. We audit everything. <strong>You walk out with a personalized roadmap of what to fix, in what order, by when.</strong> This sets the next 8 weeks up to deliver real value.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You receive</span><ul><li>Readiness audit report</li><li>Personalized fundraising roadmap</li><li>Gap-fix priority list</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">1–2<span>Weeks · Phase 2</span></div>\n          <div>\n            <div class=\"week-tag tag-create\"><span class=\"ace-mark\">C</span> Create · Content Intensive</div>\n            <div class=\"week-title\">All 6 Modules · Live · Group.</div>\n            <div class=\"week-desc\">Six live group sessions × 2 hours · 3 sessions per week × 2 weeks. All 6 content modules covered: fundraising fundamentals, market dynamics & valuations, financial modeling, pitch flow & narrative, outreach strategy, investment instruments & term sheets. <strong>Templates and exercises released alongside each session — you work them in parallel.</strong></div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You execute</span><ul><li>All exercises completed</li><li>Templates customized to your business</li><li>Draft versions of every deliverable</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">3–6<span>Weeks · Phase 3</span></div>\n          <div>\n            <div class=\"week-tag tag-create\"><span class=\"ace-mark\">C</span> Create · 1:1 Sharpening</div>\n            <div class=\"week-title\">Three 1:1 Deep-Dive Sessions.</div>\n            <div class=\"week-desc\">Founder-scheduled across 4 weeks. Three 60-min 1:1s with Gaurav: <strong>(1) Deck Teardown · (2) Financial Model + Funding Ask Review · (3) Pitch Script Refinement.</strong> You submit your work 48 hours before each call. Gaurav tears into it on the call — slide-by-slide, assumption-by-assumption. <strong>You go execute the rebuild yourself.</strong> The deliverable is yours. You own it.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You execute</span><ul><li>Rebuilt pitch deck</li><li>Defensible financial model</li><li>3-script pitch (30-sec · 2-min · 5-min)</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">5–6<span>Weeks · Phase 4</span></div>\n          <div>\n            <div class=\"week-tag tag-tests\"><span class=\"ace-mark\">E</span> Execute · Pressure Test</div>\n            <div class=\"week-title\">The Diligence Stress Test.</div>\n            <div class=\"week-desc\">When you're ready (founder books it weeks 5 or 6), you submit your full dataroom 48 hours before a live 90-min session. A practicing VC runs an actual diligence interview — same questions, same intensity, same red-flag hunting as a real diligence process. <strong>You defend in real-time. Structured gap-list written feedback after.</strong> Most founders have never been pressure-tested like this. The first time shouldn't be with a real investor.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You receive</span><ul><li>90-min recorded diligence session</li><li>Structured gap-list with priorities</li><li>Dataroom revision roadmap</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">8<span>Week · Phase 5</span></div>\n          <div>\n            <div class=\"week-tag tag-execute\"><span class=\"ace-mark\">E</span> Execute · Demo Day</div>\n            <div class=\"week-title\">Demo Day · Real Investor Panel.</div>\n            <div class=\"week-desc\">3–5 active angels and VCs sit on a panel. Each founder gets 6 min pitch + 8 min Q&A. <strong>Scored on clarity, traction credibility, market opportunity, ask defensibility, founder presence.</strong> Scorecards + full recording delivered. Group debrief next day — what landed, what didn't, what to fix before going live.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You receive</span><ul><li>Demo Day recording</li><li>Panel scoring + written feedback</li><li>Final pitch revisions list</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">8<span>Week · Bonus</span></div>\n          <div>\n            <div class=\"week-tag tag-execute\"><span class=\"ace-mark\">E</span> Execute · Outreach Prep</div>\n            <div class=\"week-title\">Customized 50-Investor Target List.</div>\n            <div class=\"week-desc\">In your final 1:1 of week 6, delivered formally at week 8: a vetted, customized list of <strong>50 investors mapped to your stage, sector, geography, and check size.</strong> Built by Gaurav. Not scraped from a database. Not a generic template. You also get the outreach framework, warm-intro pathway, and follow-up cadence — and you run the outreach yourself.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You receive</span><ul><li>Custom 50-investor list</li><li>Outreach templates + framework</li><li>Warm-intro request templates</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">∞<span>Lifetime</span></div>\n          <div>\n            <div class=\"week-tag tag-execute\"><span class=\"ace-mark\">E</span> Execute · Ongoing</div>\n            <div class=\"week-title\">Investor Roundtable · Lifetime Access.</div>\n            <div class=\"week-desc\">Monthly group sessions with a rotating panel of practicing VCs and angels. Group Q&A. Real-time feedback. Investor sentiment, sector heat, current deal terms. <strong>Yours for life as an alumnus.</strong> Even after you raise. Especially after you raise.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You receive</span><ul><li>Monthly investor panel sessions</li><li>Lifetime alumni access</li><li>Active community of raised founders</li></ul></div>\n        </div>\n\n      </div>\n\n      <!-- EXPRESS ENTRY -->\n      <div class=\"express\">\n        <div class=\"express-ico\">⚡</div>\n        <div>\n          <h4>Express Entry — for repeat VC-raised founders</h4>\n          <p>Already raised from VCs before? You don't need the content modules. Skip Phase 2. Start at the Investor Readiness Review, then go straight to 1:1 Sharpening → Diligence Stress Test → Demo Day. Same $3,997 price. ~6-week timeline instead of 8.</p>\n        </div>\n        <a href=\"#\" class=\"btn\" data-action=\"applyPage\">Apply Express →</a>\n      </div>\n\n    </div>\n  </section>\n\n  <!-- HOW 1:1 WORKS -->\n  <section class=\"vault\" style=\"background:var(--teal-deep)\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— How the 1:1 Sessions Work</div>\n        <h2 class=\"h2\">Gaurav gives the feedback. <em>You execute the rebuild.</em></h2>\n        <p class=\"section-sub\">This is not done-for-you. This is done-with-you, with a clean handoff every time. The work stays yours. So does the outcome.</p>\n      </div>\n      <div class=\"vault-grid\" style=\"grid-template-columns:repeat(4,1fr)\">\n        <div class=\"vault-item\"><div class=\"ico\">01</div><h4>You submit</h4><p>Bring the current version of your deliverable to the 1:1 call — 48 hours in advance.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">02</div><h4>Gaurav reviews live</h4><p>Tears into it on the call. Investor lens. Slide-by-slide, assumption-by-assumption. Concrete written feedback.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">03</div><h4>You execute</h4><p>Take the feedback. Rebuild. The work is yours. The artifact is yours. The skill is yours.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">04</div><h4>Async sign-off</h4><p>Send the rebuilt version. Gaurav signs off async or flags last fixes in written notes. Done.</p></div>\n      </div>\n    </div>\n  </section>\n\n  <!-- WHAT YOU LEAVE WITH -->\n  <section class=\"outcomes\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— What You Walk Out With</div>\n        <h2 class=\"h2\">Eight weeks in. <em>Investor-grade out.</em></h2>\n      </div>\n      <div class=\"outcomes-grid\">\n        <div class=\"outcome-card\"><span class=\"pill pill-yellow\">Diagnostic</span><h3>Personal Fundability Audit</h3><p>You'll know exactly where you stand. Real, written, no sugar.</p></div>\n        <div class=\"outcome-card\"><span class=\"pill pill-turq\">Materials</span><h3>Investor-Grade Pitch Deck</h3><p>Rebuilt by you. Sharpened by Gaurav. Tested at Demo Day.</p></div>\n        <div class=\"outcome-card\"><span class=\"pill pill-turq\">Materials</span><h3>Defensible Financial Model</h3><p>Ask, valuation, runway, dilution — every number you can defend live.</p></div>\n        <div class=\"outcome-card\"><span class=\"pill pill-warn\">Pressure-Tested</span><h3>The Diligence Stress Test</h3><p>You'll have survived a real VC diligence interview. Recorded. Replayable.</p></div>\n        <div class=\"outcome-card\"><span class=\"pill pill-teal\">Pitched</span><h3>Demo Day Recording</h3><p>Your full pitch + Q&A + panel scoring — usable as a fundraising asset.</p></div>\n        <div class=\"outcome-card\"><span class=\"pill pill-teal\">Investor Access</span><h3>Customized 50-Investor List</h3><p>Built by Gaurav. Stage + sector + check-size matched. Yours.</p></div>\n        <div class=\"outcome-card\"><span class=\"pill pill-teal\">Outreach</span><h3>Outreach Toolkit</h3><p>Cold + warm templates, follow-up cadence, intro pathway. You run it.</p></div>\n        <div class=\"outcome-card\"><span class=\"pill pill-yellow\">Lifetime</span><h3>Investor Roundtable Access</h3><p>Monthly group VC Q&A. Forever. Alumni community of raised founders.</p></div>\n        <div class=\"outcome-card\"><span class=\"pill pill-yellow\">Lifetime</span><h3>All Templates & Exercises</h3><p>Every framework. Every tool. Updates included. No upcharge.</p></div>\n      </div>\n    </div>\n  </section>\n\n  <!-- ANTI-SELL -->\n  <section class=\"antisell\">\n    <div class=\"wrap\">\n      <div class=\"section-head center\">\n        <div class=\"kicker\">— Real Talk Before You Apply</div>\n        <h2 class=\"h2\">Investor-Ready isn't for everyone. <em>Read this first.</em></h2>\n      </div>\n      <div class=\"antisell-grid\">\n        <div class=\"antisell-card dont\">\n          <h4>Don't apply if:</h4>\n          <ul>\n            <li>You don't have an MVP and at least some traction. Start with Foundation.</li>\n            <li>You're hoping the program will magically raise your round. It won't. You will.</li>\n            <li>You expect Gaurav to write your deck for you. He won't. That's à-la-carte.</li>\n            <li>You're not willing to execute between sessions. The 1:1s are useless if you skip the work.</li>\n            <li>You want done-for-you investor outreach. That's Program 03 (Outreach).</li>\n            <li>You can't commit ~6–8 hrs/week for 8 weeks. The cohort works on momentum.</li>\n          </ul>\n        </div>\n        <div class=\"antisell-card do\">\n          <h4>Apply if:</h4>\n          <ul>\n            <li>You have traction (revenue, pilots, real users) and want to raise in 3–6 months.</li>\n            <li>You'd rather hear \"no\" from Gaurav than \"no\" from a real VC.</li>\n            <li>You're committed to executing every week. The work between sessions is the program.</li>\n            <li>You want a Diligence Stress Test before a real one happens.</li>\n            <li>You want an investor list built for you — not a generic database.</li>\n            <li>You want lifetime access to monthly VC roundtables, even after you raise.</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- WHY NOW -->\n  <section class=\"whynow\">\n    <div class=\"wrap\">\n      <div class=\"whynow-card\">\n        <div class=\"whynow-num\">8</div>\n        <div>\n          <div class=\"kicker\">— Why Now</div>\n          <h3>A real fundraise process takes <em>4–6 months end-to-end.</em></h3>\n          <p>If you want to be in market in 3 months, your kit needs to be sharpened now. Founders who wait until they \"need to raise\" almost always raise wrong — under pressure, with the wrong investors, at the wrong terms. The 8-week Investor-Ready cohort exists so you can hit the market from a position of clarity, not panic. Cohorts cap at 20 founders. Apply early.</p>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- PRICING -->\n  <section class=\"pricing\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— Investment</div>\n        <h2 class=\"h2\">$3,997. <em>Application-based.</em></h2>\n      </div>\n      <div class=\"price-card\">\n        <div>\n          <div class=\"price-amt\">\n            $3,997\n            <small>USD + HST · per founder</small>\n            <em>Cofounder seat: +$497</em>\n          </div>\n          <div class=\"price-anchor\">\n            <strong>Compared to:</strong>\n            <ul>\n              <li>5 hours with a fundraising consultant ($800/hr × 5)</li>\n              <li>A done-for-you deck from an agency (~$3,500, no strategy)</li>\n              <li>2–3% extra dilution from a badly negotiated SAFE ($30K+ at $1M raise)</li>\n              <li>6 months of lost runway from a failed raise (~$50K+)</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"price-includes\">\n          <h4>— What's included</h4>\n          <ul>\n            <li>Pre-cohort Investor Readiness Review (1:1, 90 min)</li>\n            <li>All 6 modules taught live (weeks 1–2 · 3 sessions/week × 2hrs)</li>\n            <li>3 × 1:1 deep-dive sessions with Gaurav (weeks 3–6)</li>\n            <li>The Diligence Stress Test (weeks 5–6, founder-scheduled)</li>\n            <li>Demo Day with 3–5 real investor panel (week 8)</li>\n            <li>Customized 50-investor target list (built by Gaurav)</li>\n            <li>Investor Roundtable — lifetime alumni access</li>\n            <li>Weekly office hours throughout</li>\n            <li>All templates · exercises · tools — lifetime access</li>\n            <li>1-year recordings · 12 months updates</li>\n            <li>14-Day Truth Promise — refund if not 10x the value</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- AD-HOC LINK -->\n  <section class=\"adhoc\">\n    <div class=\"wrap\">\n      <div class=\"adhoc-inner\">\n        <div>\n          <div class=\"kicker\">— Need extra horsepower on one piece?</div>\n          <h3>Add à-la-carte services <em>on top of Investor-Ready.</em></h3>\n          <p>Some founders want Gaurav to build the financial model with them, do a deeper standalone valuation analysis, or run extra Q&A prep before a high-stakes investor meeting. Standalone services are available alongside the cohort — pick what you need.</p>\n          <a href=\"https://amgvp.com/\" class=\"btn btn-yellow\">Browse all services <span class=\"arr\">→</span></a>\n        </div>\n        <div class=\"adhoc-list\">\n          <span>Pitch Deck Creation</span>\n          <span>Financial Model Build</span>\n          <span>Valuation Analysis</span>\n          <span>Investor Q&A Prep</span>\n          <span>Fundraising Dynamics</span>\n          <span>Ask-Me-Anything 1:1</span>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- FAQ -->\n  <section class=\"faq\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— Founder Objections</div>\n        <h2 class=\"h2\">Real questions. <em>Real answers.</em></h2>\n      </div>\n      <div class=\"faq-list\">\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">\"Will Gaurav build my pitch deck and model for me?\"<span class=\"plus\">+</span></div><div class=\"faq-a\">No. The 1:1 sessions are feedback sessions — Gaurav reviews your work, gives sharp investor-lens feedback, and you go execute the rebuild yourself. The deliverable is yours. You own it. If you want done-for-you deck or model creation, those are standalone à-la-carte services. Buy them separately.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">\"Will Gaurav do investor outreach for me?\"<span class=\"plus\">+</span></div><div class=\"faq-a\">No. Investor-Ready prepares the toolkit — customized 50-investor list, outreach templates, warm-intro pathway. <strong>You run the outreach yourself.</strong> If you want done-with-you outreach where Gaurav runs the engine alongside you (with broker-dealer compliance), that's Program 03 (Outreach).</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">\"What's Express Entry?\"<span class=\"plus\">+</span></div><div class=\"faq-a\">For repeat founders who've raised from VCs before (not just angels). You don't need the content modules. Skip Phase 2. Start at the Investor Readiness Review, go straight to 1:1 sharpening → Diligence Stress Test → Demo Day. Same $3,997 price. ~6 weeks instead of 8.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">\"Why is this application-based?\"<span class=\"plus\">+</span></div><div class=\"faq-a\">Because the cohort needs founders who are actually ready to execute. We screen for real MVP, real traction, raising in 3–6 months, ability to commit to weekly work. We reject roughly 40% of applicants. Keeps the cohort tight and the peer learning sharp.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">\"What if Demo Day generates real investor interest?\"<span class=\"plus\">+</span></div><div class=\"faq-a\">It happens. Investor-Ready won't broker the deal (Program 03 handles that with proper broker-dealer licensing), but if a panel investor wants a follow-up meeting, you've got the contact and the green light. Alumni regularly land follow-ups from Demo Day panelists.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">\"Can I upgrade to Outreach (Program 03) after Investor-Ready?\"<span class=\"plus\">+</span></div><div class=\"faq-a\">Yes — and many alumni do. Investor-Ready graduates with a polished kit are exactly the profile Outreach looks for. Talk to Gaurav about the upgrade pathway during your week-8 debrief.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">\"What's the 14-Day Truth Promise?\"<span class=\"plus\">+</span></div><div class=\"faq-a\">If after the first 2 weeks (post-Diagnostic + Content Intensive) you don't think you're getting at least 10x the price in value, email Gaurav. Full refund. Keep the templates as a thank-you for trying. Most founders never claim it.</div></div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"finale\">\n    <div class=\"wrap\">\n      <h2>Get your materials <em>pressure-tested.</em></h2>\n      <p>Cohort caps at 20 founders. Application takes 15 minutes — we ask about your traction, materials, and timeline. We respond within 48 hours.</p>\n      <a href=\"#\" class=\"btn btn-yellow\" data-action=\"applyPage\">Start your application <span class=\"arr\">→</span></a>\n    </div>\n  </section>\n\n</div>\n\n<!-- ================= TRACK 3 · OUTREACH ================= -->\n<div id=\"t3-page\" class=\"track-page t3-page\">\n\n  <section class=\"thero t3-hero\">\n    <div class=\"wrap\">\n      <button class=\"thero-back\" data-action=\"home\">← All Programs</button>\n      <div class=\"thero-grid\">\n        <div>\n          <div class=\"thero-eyebrow\">Program 03 · Outreach Engagement</div>\n          <h1 class=\"thero-title\">You have the kit. We have the <em>investors.</em> Let's close.</h1>\n          <div class=\"thero-ace\">\n            <span class=\"ace-chip\">E</span> Pure Execute — the final stage of the ACE Fundability Method™\n          </div>\n          <p class=\"thero-sub\">For investor-ready founders who don't need a course — they need access and execution. Done-with-you investor outreach over ~6 months. Kit audit, vetted target list, managed outreach cadence, meeting prep, due diligence support, and term-sheet negotiation. Run in partnership with a registered broker-dealer for full regulatory compliance.</p>\n          <div class=\"hero-ctas\">\n            <a href=\"#\" class=\"btn btn-primary\" data-action=\"applyPage\">Apply now <span class=\"arr\">→</span></a>\n            <a href=\"#t3-pricing\" class=\"btn btn-ghost\">See fee structures</a>\n          </div>\n          <div class=\"thero-meta\">\n            <div class=\"thero-mcell\"><div class=\"lbl\">Format</div><div class=\"val\">~6-Mo Engagement</div></div>\n            <div class=\"thero-mcell\"><div class=\"lbl\">Delivery</div><div class=\"val\">1:1 Done-With-You</div></div>\n            <div class=\"thero-mcell\"><div class=\"lbl\">Compliance</div><div class=\"val\">Broker-Dealer Partner</div></div>\n            <div class=\"thero-mcell\"><div class=\"lbl\">Spots</div><div class=\"val\">Selective · Rolling</div></div>\n          </div>\n        </div>\n        <div class=\"thero-visual\">\n          <div class=\"visual-card\">\n            <div class=\"vc-badge\">Outreach</div>\n            <div class=\"vc-title\" style=\"margin-top:28px\">Engagement Snapshot</div>\n            <div class=\"vc-line\"><span class=\"l\">Vetted target investors</span><span class=\"v\">50–100</span></div>\n            <div class=\"vc-line\"><span class=\"l\">Engagement length</span><span class=\"v\">~6 months</span></div>\n            <div class=\"vc-line\"><span class=\"l\">Founder hours saved</span><span class=\"v\">100–200+</span></div>\n            <div class=\"vc-line\"><span class=\"l\">Weekly 1:1 calls</span><span class=\"v\">Yes</span></div>\n            <div class=\"vc-line\"><span class=\"l\">Term-sheet support</span><span class=\"v\">Included</span></div>\n            <div class=\"vc-line\"><span class=\"l\">Investor Roundtable</span><span class=\"v\">Lifetime</span></div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"duo\">\n    <div class=\"wrap\">\n      <div class=\"duo-grid\">\n        <div class=\"duo-card bad\">\n          <h3>You don't need a course.</h3>\n          <p class=\"sub\">— You need access and execution.</p>\n          <ul class=\"duo-list\">\n            <li>Your pitch deck, model, and dataroom are already investor-grade. You've done the work.</li>\n            <li>You have real traction — revenue, pilots, retention numbers — that make you fundable today.</li>\n            <li>You've burned weeks on cold outreach lists that don't convert and warm intros that fizzle.</li>\n            <li>You don't have time to source 100 investors, vet them, write 100 emails, and chase follow-ups.</li>\n            <li>When term sheets land, you want someone who can read every clause and negotiate the dangerous ones out.</li>\n          </ul>\n        </div>\n        <div class=\"duo-card good\">\n          <h3>Here's the engine.</h3>\n          <p class=\"sub\">— What we run alongside you.</p>\n          <ul class=\"duo-list\">\n            <li>50–100 vetted, stage-matched target investors built specifically for your raise.</li>\n            <li>Cold outreach + warm-intro pathway managed to actually generate meetings.</li>\n            <li>Pre-meeting prep + post-meeting debriefs on every investor conversation that matters.</li>\n            <li>Term-sheet review and negotiation coaching when offers come in.</li>\n            <li>2 fee structures: cash + success fee, or lower cash + success fee + advisory shares.</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- 6-STEP ENGINE -->\n  <section class=\"curriculum\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— The Outreach Engine · Pure Execute</div>\n        <h2 class=\"h2\">Six steps. <em>One outcome.</em></h2>\n        <p class=\"section-sub\">A systematic process. Step 1 is the final Assess checkpoint of the ACE Method. Steps 2–6 are pure Execute — the work that turns a polished kit into actual investor meetings and term sheets.</p>\n      </div>\n      <div class=\"weekly\">\n\n        <div class=\"week\">\n          <div class=\"week-num\">01<span>Step · Onboarding</span></div>\n          <div>\n            <div class=\"week-tag tag-assess\"><span class=\"ace-mark\">A</span> Final Assess</div>\n            <div class=\"week-title\">Investment Readiness Audit.</div>\n            <div class=\"week-desc\">We audit your full current state — business hygiene, corporate structure, teaser, deck, financial model, dataroom. Sign-off: you're ready to engage. <strong>If we find gaps, we redirect you to Investor-Ready or specific à-la-carte services first.</strong> We don't take engagements that aren't fundable.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You receive</span><ul><li>Readiness audit report</li><li>Gap-fix list (if any)</li><li>Outreach execution plan</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">02<span>Step · Targeting</span></div>\n          <div>\n            <div class=\"week-tag tag-execute\"><span class=\"ace-mark\">E</span> Execute</div>\n            <div class=\"week-title\">Vetted Target Investor List.</div>\n            <div class=\"week-desc\">50–100 active investors filtered by stage, sector, geography, check size, and recent activity. <strong>Vetted with you — you approve every name.</strong> Saves 20+ hours of database digging and LinkedIn rabbit holes.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You receive</span><ul><li>Filtered investor CRM</li><li>Investor profile briefs</li><li>Founder approval round</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">03<span>Step · Outreach</span></div>\n          <div>\n            <div class=\"week-tag tag-execute\"><span class=\"ace-mark\">E</span> Execute</div>\n            <div class=\"week-title\">Cold + Warm Outreach.</div>\n            <div class=\"week-desc\">Customized teaser. Ambassador army activated for warm intros. Outreach launched to the target list to generate investor meetings. Saves 10+ hours of execution time. Live CRM with response rates and meeting status.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You receive</span><ul><li>Customized teaser</li><li>Outreach launched</li><li>Live response dashboard</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">04<span>Step · Meetings</span></div>\n          <div>\n            <div class=\"week-tag tag-execute\"><span class=\"ace-mark\">E</span> Execute</div>\n            <div class=\"week-title\">Pre-Meeting Prep + Debriefs.</div>\n            <div class=\"week-desc\">Before each first meeting: 30-min prep call on the specific investor, their thesis, likely questions. After: debrief, decode their feedback, plan the follow-up. Ongoing during the entire investor meeting cycle. 10+ hours saved.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You receive</span><ul><li>Pre-meeting briefs</li><li>Live debrief calls</li><li>Follow-up templates</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">05<span>Step · Diligence</span></div>\n          <div>\n            <div class=\"week-tag tag-execute\"><span class=\"ace-mark\">E</span> Execute</div>\n            <div class=\"week-title\">Business-Specific Q&A + Diligence Support.</div>\n            <div class=\"week-desc\">When investors enter diligence, we help you address every business-specific question — financial, operational, legal, technical. Your dataroom stays organized. <strong>You answer faster than 95% of founders.</strong> 8–10 hours saved.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You receive</span><ul><li>Custom Q&A response support</li><li>Dataroom maintenance</li><li>Diligence checklist tracking</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">06<span>Step · Close</span></div>\n          <div>\n            <div class=\"week-tag tag-execute\"><span class=\"ace-mark\">E</span> Execute</div>\n            <div class=\"week-title\">Term Sheet + Negotiation + Close.</div>\n            <div class=\"week-desc\">When term sheets land, we read every clause — valuation cap, MFN, liquidation preference, board seats, drag-along, anti-dilution. We coach you through negotiation. We help close the round. 8–10 hours saved.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You receive</span><ul><li>Term-sheet review</li><li>Negotiation coaching</li><li>Round close support</li></ul></div>\n        </div>\n\n      </div>\n    </div>\n  </section>\n\n  <!-- COMPLIANCE -->\n  <section class=\"vault\" style=\"background:var(--teal-deep)\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— Regulatory Compliance</div>\n        <h2 class=\"h2\">Run in partnership with a <em>registered broker-dealer.</em></h2>\n        <p class=\"section-sub\">Securities solicitation across our jurisdictions requires proper licensing. Outreach is operated in partnership with a registered broker-dealer to keep every step compliant — from outreach to term sheet to round close.</p>\n      </div>\n      <div class=\"vault-grid\" style=\"grid-template-columns:repeat(3,1fr)\">\n        <div class=\"vault-item\"><div class=\"ico\">✓</div><h4>Licensed Partner</h4><p>Engagements run alongside a registered broker-dealer. Every solicitation step is compliant with applicable securities regulation.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">✓</div><h4>Transparent Fees</h4><p>Two structures — cash + success fee, or lower cash + success fee + advisory shares. Documented up front. Negotiable. No hidden carry.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">✓</div><h4>Multi-Geography</h4><p>Operational in North America, Europe, the UK, the Middle East, and Africa. Regulatory requirements mapped per jurisdiction.</p></div>\n      </div>\n    </div>\n  </section>\n\n  <!-- 3 PRICING -->\n  <section class=\"pricing\" id=\"t3-pricing\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— Two Fee Structures</div>\n        <h2 class=\"h2\">Pick the structure that fits <em>how you want to align.</em></h2>\n        <p class=\"section-sub\">Same engagement scope. Different ways to share the upside. Pure cash + success fee, or lower cash + success fee + advisory shares.</p>\n      </div>\n\n      <div class=\"t3-pricing\" style=\"grid-template-columns:repeat(2,1fr);max-width:880px;margin-left:auto;margin-right:auto\">\n\n        <div class=\"t3-price\">\n          <div class=\"opt-name\">Option 01 · Cash + Success</div>\n          <h4>The Straight Engagement.</h4>\n          <p class=\"opt-sub\">— No equity. Success fee aligned.</p>\n          <div class=\"opt-amt\">$8,000<small> USD</small></div>\n          <div class=\"opt-extra\"><strong>+ Success fee: 4%–8%</strong> of capital raised<br>\n          · Excludes standalone non-dilutive grants<br>\n          · Includes match-funding &amp; dilutive raises<br>\n          · Success fee scales down for raises &gt; $2M</div>\n          <a href=\"#\" data-action=\"applyPage\" class=\"btn btn-ghost\" style=\"border-color:var(--teal-deep);width:100%;justify-content:center\">Apply <span class=\"arr\">→</span></a>\n        </div>\n\n        <div class=\"t3-price featured\">\n          <div class=\"pf-tag\">Most Aligned</div>\n          <div class=\"opt-name\">Option 02 · Cash + Success + Shares</div>\n          <h4>The Aligned Engagement.</h4>\n          <p class=\"opt-sub\">— Lower upfront. Skin in the game.</p>\n          <div class=\"opt-amt\">$4,000<small> USD</small></div>\n          <div class=\"opt-extra\"><strong>+ Success fee: 4%–5%</strong> of capital raised<br>\n          <strong>+ Advisory shares: 1%</strong> (vested over 24 months)<br>\n          · Excludes standalone non-dilutive grants<br>\n          · Includes match-funding &amp; dilutive raises</div>\n          <a href=\"#\" data-action=\"applyPage\" class=\"btn btn-primary\" style=\"width:100%;justify-content:center\">Apply <span class=\"arr\">→</span></a>\n        </div>\n\n      </div>\n\n      <div class=\"compliance\">\n        <div class=\"compliance-ico\">i</div>\n        <div>\n          <h4>On fees, taxes, and negotiation.</h4>\n          <p><strong>All pricing is negotiable</strong> based on raise size, stage, sector, and founder profile. The structures above are the starting points. <strong>Applicable sales taxes (HST/GST/VAT), payment processing fees, and any third-party charges are extra</strong> and billed at cost. Success fees are documented through the registered broker-dealer partner. Engagements below $/€2M are accepted on a selective basis.</p>\n        </div>\n      </div>\n\n      <div style=\"margin-top:48px\">\n        <div class=\"section-head\">\n          <div class=\"kicker\">— Where Your 100–200+ Hours Go</div>\n          <h2 class=\"h2\">What we save you. <em>Concretely.</em></h2>\n        </div>\n        <div style=\"background:#fff;border:1.5px solid var(--line);border-radius:16px;overflow:hidden;margin-top:32px\">\n          <table style=\"width:100%;border-collapse:collapse\">\n            <thead>\n              <tr style=\"background:var(--teal-deep);color:#fff\">\n                <th style=\"text-align:left;padding:16px 24px;font-family:'JetBrains Mono',monospace;font-size:11.5px;font-weight:700;text-transform:uppercase;letter-spacing:0.14em\">Activity</th>\n                <th style=\"text-align:right;padding:16px 24px;font-family:'JetBrains Mono',monospace;font-size:11.5px;font-weight:700;text-transform:uppercase;letter-spacing:0.14em;width:200px\">Founder Time Saved</th>\n              </tr>\n            </thead>\n            <tbody>\n              <tr style=\"border-bottom:1px solid var(--line)\"><td style=\"padding:16px 24px;font-size:15px;color:var(--ink)\">Investor research and filtering</td><td style=\"padding:16px 24px;text-align:right;font-family:'Fraunces',serif;font-weight:600;font-size:17px;color:var(--teal-deep)\">20+ hours</td></tr>\n              <tr style=\"border-bottom:1px solid var(--line);background:var(--cream)\"><td style=\"padding:16px 24px;font-size:15px;color:var(--ink)\">Investor outreach setup and guidance</td><td style=\"padding:16px 24px;text-align:right;font-family:'Fraunces',serif;font-weight:600;font-size:17px;color:var(--teal-deep)\">10+ hours</td></tr>\n              <tr style=\"border-bottom:1px solid var(--line)\"><td style=\"padding:16px 24px;font-size:15px;color:var(--ink)\">Investor meeting preparation and follow-up</td><td style=\"padding:16px 24px;text-align:right;font-family:'Fraunces',serif;font-weight:600;font-size:17px;color:var(--teal-deep)\">20+ hours</td></tr>\n              <tr style=\"border-bottom:1px solid var(--line);background:var(--cream)\"><td style=\"padding:16px 24px;font-size:15px;color:var(--ink)\">Investor Q&amp;A and due diligence support</td><td style=\"padding:16px 24px;text-align:right;font-family:'Fraunces',serif;font-weight:600;font-size:17px;color:var(--teal-deep)\">10+ hours <span style=\"font-family:'Inter Tight';font-weight:400;font-size:12px;color:var(--ink-soft)\">/ investor</span></td></tr>\n              <tr style=\"border-bottom:1px solid var(--line)\"><td style=\"padding:16px 24px;font-size:15px;color:var(--ink)\">Negotiation guidance</td><td style=\"padding:16px 24px;text-align:right;font-family:'Fraunces',serif;font-weight:600;font-size:17px;color:var(--teal-deep)\">8–10 hours</td></tr>\n              <tr><td style=\"padding:16px 24px;font-size:15px;color:var(--ink);background:var(--cream)\">Process organization, tracking, and closing coordination</td><td style=\"padding:16px 24px;text-align:right;font-family:'Fraunces',serif;font-weight:600;font-size:17px;color:var(--teal-deep);background:var(--cream)\">20+ hours</td></tr>\n              <tr style=\"background:var(--yellow-soft);border-top:2px solid var(--yellow)\"><td style=\"padding:18px 24px;font-size:16px;color:var(--teal-deep);font-weight:700;font-family:'Fraunces',serif\">Total estimated founder time saved</td><td style=\"padding:18px 24px;text-align:right;font-family:'Fraunces',serif;font-weight:700;font-size:22px;color:var(--teal-deep)\">100–200+ hours</td></tr>\n            </tbody>\n          </table>\n        </div>\n      </div>\n\n    </div>\n  </section>\n\n  <!-- ANTI-SELL -->\n  <section class=\"antisell\">\n    <div class=\"wrap\">\n      <div class=\"section-head center\">\n        <div class=\"kicker\">— Real Talk Before You Engage</div>\n        <h2 class=\"h2\">Outreach isn't for everyone. <em>We're selective by design.</em></h2>\n      </div>\n      <div class=\"antisell-grid\">\n        <div class=\"antisell-card dont\">\n          <h4>Don't engage if:</h4>\n          <ul>\n            <li>Your pitch deck, model, or dataroom isn't investor-grade. Fix that first.</li>\n            <li>You expect us to guarantee meetings or capital. No legitimate partner can.</li>\n            <li>You don't have real traction. Outreach won't manufacture it.</li>\n            <li>You want a flat-rate consultant. The 2 fee structures are deliberate — and negotiable.</li>\n            <li>You're not in a sector or geography we operate in. We'll tell you on the fit call.</li>\n          </ul>\n        </div>\n        <div class=\"antisell-card do\">\n          <h4>Engage if:</h4>\n          <ul>\n            <li>Your kit is genuinely investor-ready and you've validated it (Investor-Ready alumni qualify).</li>\n            <li>You want to save 100–200+ hours that founders typically burn on list-building, outreach, meeting prep, diligence Q&A, and closing coordination.</li>\n            <li>You want compliant, broker-dealer-partnered solicitation across multiple jurisdictions.</li>\n            <li>You want term-sheet support when offers come in — not just intros.</li>\n            <li>You want Gaurav's investor network + active angel syndicate access.</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- AD-HOC -->\n  <section class=\"adhoc\">\n    <div class=\"wrap\">\n      <div class=\"adhoc-inner\">\n        <div>\n          <div class=\"kicker\">— Not quite ready for Outreach?</div>\n          <h3>Sharpen one piece of your kit <em>before we engage.</em></h3>\n          <p>Outreach starts with a readiness audit. If we find gaps in your deck, model, valuation, or Q&A, we'll redirect you to standalone services to fix those first — then start outreach with a sharp, complete kit. Better to spend two weeks fixing than three months pitching a flawed package.</p>\n          <a href=\"https://amgvp.com/\" class=\"btn btn-yellow\">Browse all services <span class=\"arr\">→</span></a>\n        </div>\n        <div class=\"adhoc-list\">\n          <span>Investor Readiness Review</span>\n          <span>Pitch Deck Review</span>\n          <span>Financial Model Build</span>\n          <span>Valuation Analysis</span>\n          <span>Q&A + Diligence Prep</span>\n          <span>Ask-Me-Anything 1:1</span>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- FAQ -->\n  <section class=\"faq\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— Founder Objections</div>\n        <h2 class=\"h2\">Real questions. <em>Real answers.</em></h2>\n      </div>\n      <div class=\"faq-list\">\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">\"Are you a registered broker-dealer?\"<span class=\"plus\">+</span></div><div class=\"faq-a\">Outreach is run in partnership with a registered broker-dealer license holder to ensure full compliance with securities regulation in the jurisdictions we operate. The licensed partner handles the regulated aspects of solicitation; Gaurav runs strategy, materials, and meeting support. All fee arrangements are documented and compliant.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">\"What if my kit isn't ready?\"<span class=\"plus\">+</span></div><div class=\"faq-a\">We won't start outreach with a flawed kit — it wastes your runway and burns investor goodwill. If the readiness audit flags major gaps, we redirect you to Investor-Ready (cohort) or specific à-la-carte services first. Then we engage. We're selective about which engagements we take.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">\"Can you guarantee meetings or capital raised?\"<span class=\"plus\">+</span></div><div class=\"faq-a\">No. No legitimate fundraising partner can. What we guarantee: a vetted target list, executed outreach, prep + debrief on every meeting, term-sheet support. We take engagements where we believe the raise is viable. We don't take engagements where it isn't.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">\"Which fee structure should I pick?\"<span class=\"plus\">+</span></div><div class=\"faq-a\">If you prefer no equity dilution → Option 01 (Cash $8K + 4–8% success fee). If preserving runway matters more → Option 02 (Cash $4K + 4–5% success fee + 1% advisory shares). Both are negotiable based on your raise size, stage, and sector. We discuss it on the fit call.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">\"What sectors and stages do you work with?\"<span class=\"plus\">+</span></div><div class=\"faq-a\">Tech startups at pre-seed through Series A primarily. Active sectors: ClimateTech, AI/ML, Digital Health, Medical Device, Hardware, Supply Chain, Fintech. Geographies: North America, Europe, the UK, the Middle East, and Africa.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">\"What does '100–200+ hours saved' actually mean?\"<span class=\"plus\">+</span></div><div class=\"faq-a\">Concretely: 20+ hours on investor research and filtering, 10+ on outreach setup and guidance, 20+ on meeting prep and follow-up, 10+ per investor on Q&A and diligence support, 8–10 on negotiation guidance, 20+ on process organization, tracking, and closing coordination. Founders who try this alone burn the time and learn it's not the highest-leverage use of their week.</div></div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"finale\">\n    <div class=\"wrap\">\n      <h2>Ready to <em>engage?</em></h2>\n      <p>Outreach starts with a 30-minute fit call. We assess readiness, walk through the 2 fee structures, and decide if it's a match. No pitch deck required for the call.</p>\n      <a href=\"#\" class=\"btn btn-yellow\" data-action=\"applyPage\">Apply now <span class=\"arr\">→</span></a>\n    </div>\n  </section>\n\n</div>\n\n<!-- =================== FOOTER =================== -->\n<footer class=\"foot\">\n  <div class=\"wrap\">\n    <div class=\"foot-row\">\n      <div>© 2026 Investor-Ready · Run by Gaurav Bansal</div>\n      <div>Track 3 operated in partnership with a registered broker-dealer.</div>\n    </div>\n  </div>\n</footer>" +"<div id=\"about-page\" class=\"track-page about-page\">"+ aboutSection +"</div><div id=\"call-page\" class=\"track-page inquiry-page\"><section class=\"inquiry\"><div class=\"wrap\"><button class=\"thero-back\" data-action=\"home\">← Back</button><div class=\"inquiry-grid\"><div><div class=\"kicker\">Strategy Call</div><h1 class=\"thero-title\">Book your strategy call.</h1><p class=\"thero-sub\">Tell us where you are in the fundraising journey. We will review your details and get back to you with the right next step.</p></div><form class=\"inquiry-form\" id=\"strategycall\"> <input type=\"hidden\" name=\"_subject\" value=\"New strategy call request - Investment Readiness Program\"><input type=\"hidden\" name=\"_captcha\" value=\"false\">     <input type=\"hidden\" name=\"_webhook\" value=\"https://script.google.com/macros/s/AKfycbzVII_B1IctdseS9GxxbFNWBeHznGTnMbEZnCg_5R_Y9YFMPY-G252d9uR7UYaGRTtx/exec\"> <!-- helps identify which form --><input type=\"hidden\" name=\"Request type\" value=\"Strategy Call\"><label>Full name<input name=\"Full name\" required></label><label>Email<input type=\"email\" name=\"Email\" required></label><label>Company / startup name<input name=\"Company\"></label><label>Startup stage<select name=\"Startup stage\" required><option value=\"\">Select stage</option><option>Idea / Pre-MVP</option><option>MVP built</option><option>Post-MVP with traction</option><option>Investor-ready / actively raising</option></select></label><label>What do you need help with?<textarea name=\"What they need help with\" rows=\"5\" required></textarea></label><button class=\"btn btn-primary\" type=\"submit\">Send request <span class=\"arr\">→</span></button></form></div></div></section></div><div id=\"apply-page\" class=\"track-page inquiry-page\"><section class=\"inquiry\"><div class=\"wrap\"><button class=\"thero-back\" data-action=\"home\">← Back</button><div class=\"inquiry-grid\"><div><div class=\"kicker\">Application</div><h1 class=\"thero-title\">Apply to the Investment Readiness Program.</h1><p class=\"thero-sub\">Share a few details about your company, stage, and fundraising timeline. Applications are reviewed within 48 hours.</p></div><form class=\"inquiry-form\" id=\"newProgramApplication\"><input type=\"hidden\" name=\"_subject\" value=\"New program application - Investment Readiness Program\"><input type=\"hidden\" name=\"_webhook\" value=\"https://script.google.com/macros/s/AKfycbzVII_B1IctdseS9GxxbFNWBeHznGTnMbEZnCg_5R_Y9YFMPY-G252d9uR7UYaGRTtx/exec\"> <!-- helps identify which form --><input type=\"hidden\" name=\"_captcha\" value=\"false\"><input type=\"hidden\" name=\"Request type\" value=\"Program Application\"><label>Full name<input name=\"Full name\" required></label><label>Email<input type=\"email\" name=\"Email\" required></label><label>Company / startup name<input name=\"Company\" required></label><label>Which track are you interested in?<select name=\"Track interest\" required><option value=\"\">Select track</option><option>Track 1 - Foundation</option><option>Track 2 - Accelerator</option><option>Track 3 - Investor Outreach</option><option>Not sure yet</option></select></label><label>Current traction / stage<textarea name=\"Current traction or stage\" rows=\"4\" required></textarea></label><label>Fundraising timeline<textarea name=\"Fundraising timeline\" rows=\"4\" required></textarea></label><button class=\"btn btn-primary\" type=\"submit\">Submit application <span class=\"arr\">→</span></button></form></div></div></section></div>";
function scrollToId(id) {
  window.setTimeout(() => {
    document.getElementById(id)?.scrollIntoView({ behavior: 'smooth' })
  }, 50)
}

const PAGE_ROUTES = {
  landing: '/',
  t1: '/track-1',
  t2: '/track-2',
  t3: '/track-3',
  about: '/about',
  apply: '/apply',
  call: '/strategy-call',
}

const ROUTE_PAGES = {
  '/': 'landing',
  '/track-1': 't1',
  '/track-2': 't2',
  '/track-3': 't3',
  '/about': 'about',
  '/apply': 'apply',
  '/strategy-call': 'call',
}

const SERVICES_ROUTE = '/services'
const SERVICES_URL = 'https://amgvp.com/'

function normalizePath(pathname) {
  const normalized = pathname.replace(/\/+$/, '')
  return normalized || '/'
}

function getPageFromPath(pathname) {
  return ROUTE_PAGES[normalizePath(pathname)] || 'landing'
}

export default function App() {
  const [page, setPage] = useState(() => getPageFromPath(window.location.pathname))
const [showPopup, setShowPopup] = useState(false)
const [loading, setLoading] = useState(false)

const handleSubmit = async (e) => {
  e.preventDefault()
setLoading(true)
  if (loading) return

  setLoading(true)

  const submitButton = document.querySelector(
    '#customForm button[type=\"submit"]'
  )

  if (submitButton) {
    submitButton.disabled = true
    submitButton.innerHTML = 'Submitting...'
    submitButton.style.opacity = '0.7'
    submitButton.style.cursor = 'not-allowed'
  }

  const formData = new FormData(e.target)

  try {
    const response = await fetch(
      'https://formsubmit.co/ajax/manishpanda24@gmail.com',
      {
        method: 'POST',
        body: formData,
      }
    )

    const data = await response.json()

    if (data.success) {
      setShowPopup(true)
      e.target.reset()
    }
  } catch (error) {
    console.error(error)
  }



  if (submitButton) {
    submitButton.disabled = false
    submitButton.innerHTML = 'Send request →'
    submitButton.style.opacity = '1'
    submitButton.style.cursor = 'pointer'
  }
    setLoading(false)
}

useEffect(() => {
  if (normalizePath(window.location.pathname) === SERVICES_ROUTE) {
    window.location.replace(SERVICES_URL)
    return undefined
  }

  const handlePopState = () => {
    if (normalizePath(window.location.pathname) === SERVICES_ROUTE) {
      window.location.replace(SERVICES_URL)
      return
    }

    setPage(getPageFromPath(window.location.pathname))
    window.scrollTo({ top: 0, behavior: 'instant' })
  }

  window.addEventListener('popstate', handlePopState)
  return () => window.removeEventListener('popstate', handlePopState)
}, [])

const navigateToPage = useCallback((nextPage, options = {}) => {
  const nextRoute = PAGE_ROUTES[nextPage] || PAGE_ROUTES.landing
  const currentRoute = `${window.location.pathname}${window.location.hash}`

  setPage(nextPage)

  if (currentRoute !== nextRoute) {
    window.history.pushState({}, '', nextRoute)
  }

  if (options.scroll !== false) {
    window.scrollTo({ top: 0, behavior: 'instant' })
  }
}, [])

useEffect(() => {
  const attachFormListeners = () => {
    const forms = document.querySelectorAll('.inquiry-form')

    forms.forEach((form) => {
      form.removeEventListener('submit', handleSubmit)
      form.addEventListener('submit', handleSubmit)
    })
  }

  const timer = setTimeout(() => {
    attachFormListeners()
  }, 500)

  return () => clearTimeout(timer)
}, [page])
  const handleClick = useCallback((event) => {
    const target = event.target
    if (!(target instanceof Element)) return

  const trackLink = target.closest('[data-track]')
    if (trackLink) {
      event.preventDefault()
      const nextPage = trackLink.getAttribute('data-track')
      navigateToPage(nextPage)
      return
    }

    const actionLink = target.closest('[data-action]')
    if (actionLink) {
      const action = actionLink.getAttribute('data-action')
      event.preventDefault()

      if (action === 'faq') {
        actionLink.closest('.faq-item')?.classList.toggle('open')
        return
      }

      if (action === 'services') {
        window.history.pushState({}, '', SERVICES_ROUTE)
        window.location.assign(SERVICES_URL)
        return
      }

      if (action === 'applyPage') {
        navigateToPage('apply')
        return
      }

      if (action === 'callPage') {
        navigateToPage('call')
        return
      }

      if (action === 'finale') {
        if (window.location.pathname !== '/' || window.location.hash !== '#finale') {
          window.history.pushState({}, '', '/#finale')
        }
        setPage('landing')
        scrollToId('finale')
        return
      }

      navigateToPage('landing')
      return
    }

    const emptyAnchor = target.closest('a[href=\"#"]')
    if (emptyAnchor) {
      event.preventDefault()
    }
  }, [navigateToPage])
return (
  <>
    <main
      className="app-shell"
      data-page={page}
      onClick={handleClick}
      dangerouslySetInnerHTML={{ __html: pageHtml }}
    />
{loading && (
  <div
    style={{
      position: 'fixed',
      inset: 0,
      background: 'rgba(0,0,0,0.45)',
      backdropFilter: 'blur(4px)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      zIndex: 99999,
    }}
  >
    <div
      style={{
        width: '70px',
        height: '70px',
        border: '4px solid rgba(255,255,255,0.15)',
        borderTop: '4px solid #8ec5ff',
        borderRadius: '50%',
        animation: 'spinLoader 0.8s linear infinite',
      }}
    />
  </div>
)}
  {showPopup && (
  <div
    style={{
      position: 'fixed',
      top: 0,
      left: 0,
      width: '100%',
      height: '100%',
      background: 'rgba(0,0,0,0.6)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      zIndex: 9999,
    }}
  >
    <div
      style={{
        background: '#fff',
        padding: '40px',
        borderRadius: '20px',
        width: '90%',
        maxWidth: '450px',
        textAlign: 'center',
        boxShadow: '0 20px 60px rgba(0,0,0,0.2)',
        fontFamily: 'Arial',
      }}
    >
      <div style={{ fontSize: '50px', marginBottom: '15px' }}>
        ✅
      </div>

      <h2
        style={{
          fontSize: '32px',
          marginBottom: '12px',
          color: '#111',
        }}
      >
        Application Submitted
      </h2>

      <p
        style={{
          color: '#555',
          lineHeight: '1.6',
          marginBottom: '25px',
          fontSize: '16px',
        }}
      >
        Thank you for applying. Our team will connect with you shortly.
      </p>

    <button
  onClick={() => {
    setShowPopup(false)
    setPage('home')
    window.scrollTo(0, 0)
  }}
        style={{
          background: '#021826',
          color: '#fff',
          border: 'none',
          padding: '14px 28px',
          borderRadius: '10px',
          cursor: 'pointer',
          fontSize: '16px',
          fontWeight: '600',
        }}
      >
        Close
      </button>
    </div>
  </div>
)}
  </>
)
}
